/* Similar: styling a container for scrolling */
.scrollable-box {
  width: 500px;
  height: 200px;
  overflow: auto;
}

/* Example of styling child items */
.item {
  width: 100%;
  height: 100%;
  background-color: coral;
}

/* Similar: enabling horizontal scroll snap */
.scroll-container {
  scroll-snap-type: x mandatory;
}

/* Similar: aligning an element within its container */
.aligned-item {
  align-self: start;
}

/* Similar: changing a CSS property value */
.container {
  scroll-snap-type: x proximity;
}

/* Similar: changing alignment in a flex container */
.item {
  align-self: center;
}

/* Similar: adding padding to a scrolling container */
.scroll-wrapper {
  scroll-padding: 1rem;
}

/* Similar: creating a new container with different scroll behavior */
.horizontal-scroll-container {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  width: 100%;
  height: 200px;
}

.horizontal-item {
  flex: 0 0 auto;
  width: 300px;
  height: 100%;
  scroll-snap-align: start;
  background-color: lightblue;
  margin-right: 10px;
}
